const AB = '123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz';
// independent impl: BigInt based
function enc(buf){
  let z=0; while(z<buf.length && buf[z]===0) z++;
  let acc=0n; for(const b of buf.subarray(z)) acc=acc*256n+BigInt(b);
  let out=''; while(acc>0n){ out=AB[Number(acc%58n)]+out; acc/=58n; }
  return '1'.repeat(z)+out;
}
function dec(s){
  const orig=s.length; let i=0; while(i<s.length && s[i]==='1') i++;
  const z=i; let acc=0n;
  for(const ch of s.slice(i)){ const d=AB.indexOf(ch); if(d<0) throw new Error('bad '+ch); acc=acc*58n+BigInt(d); }
  const bytes=[]; while(acc>0n){ bytes.unshift(Number(acc%256n)); acc/=256n; }
  return Buffer.concat([Buffer.alloc(z,0), Buffer.from(bytes)]);
}
// python bytes repr
function brepr(buf){
  const has27=buf.includes(0x27), has22=buf.includes(0x22);
  const q = (has27 && !has22) ? '"' : "'";
  let s='b'+q;
  for(const b of buf){
    if(b===0x5c) s+='\\\\';
    else if(b===0x09) s+='\\t';
    else if(b===0x0a) s+='\\n';
    else if(b===0x0d) s+='\\r';
    else if(b===q.charCodeAt(0)) s+='\\'+q;
    else if(b<0x20||b>=0x7f) s+='\\x'+b.toString(16).padStart(2,'0');
    else s+=String.fromCharCode(b);
  }
  return s+q;
}
module.exports={AB,enc,dec,brepr};
EOF
